SELECT * FROM knowledge_points WHERE name LIKE CONCAT(#{name}, '%')
AND category = #{category}
ORDER BY article_count ASC LIMIT 5

SELECT * FROM knowledge_points WHERE 1=1
AND (name LIKE CONCAT('%', #{keyword}, '%') OR keywords LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND type = #{type}
AND category = #{category}
ORDER BY importance_score DESC, article_count DESC
